import{_ as a,o as e,c as t,a2 as o}from"./chunks/framework.D21_4UK8.js";const p=JSON.parse('{"title":"📚 スタジオ・ジャーナル (The Lab Journal)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/journal.md","filePath":"ja/journal.md"}'),s={name:"ja/journal.md"};function i(c,r,n,d,l,m){return e(),t("div",null,[...r[0]||(r[0]=[o('<h1 id="📚-スタジオ・ジャーナル-the-lab-journal" tabindex="-1">📚 スタジオ・ジャーナル (The Lab Journal) <a class="header-anchor" href="#📚-スタジオ・ジャーナル-the-lab-journal" aria-label="Permalink to &quot;📚 スタジオ・ジャーナル (The Lab Journal)&quot;">​</a></h1><h3 id="音響工学、キャビネット音響、そしてクラシック・トーンの歴史を巡る探求" tabindex="-1">音響工学、キャビネット音響、そしてクラシック・トーンの歴史を巡る探求 <a class="header-anchor" href="#音響工学、キャビネット音響、そしてクラシック・トーンの歴史を巡る探求" aria-label="Permalink to &quot;音響工学、キャビネット音響、そしてクラシック・トーンの歴史を巡る探求&quot;">​</a></h3><p><strong>Main St Audio Labs</strong></p><hr><p>Main St Audio Labs <strong>スタジオ・ジャーナル</strong>へようこそ。ここでは、マイク録音技術、スピーカーの物理特性、位相整合、真空管回路設計、そして私たちのプラグイン開発を刺激する歴史的名盤の制作秘話に関する詳細な技術記事をお届けします。</p><hr><h2 id="🎛️-音響工学-ミキシング技術" tabindex="-1">🎛️ 音響工学＆ミキシング技術 <a class="header-anchor" href="#🎛️-音響工学-ミキシング技術" aria-label="Permalink to &quot;🎛️ 音響工学＆ミキシング技術&quot;">​</a></h2><div class="rock-grid" style="margin-top:1.5rem;margin-bottom:2.5rem;"><div class="rock-card"><div class="rock-card-content"><div style="font-size:0.75rem;text-transform:uppercase;color:var(--vp-c-brand-1);font-weight:bold;margin-bottom:0.35rem;">音響工学＆ミキシング</div><h3 class="rock-card-title" style="font-size:1.15rem;margin-bottom:0.5rem;">完全ガイド：1x12 Hardwood キャビネット＆マイク収録</h3><p class="rock-card-desc" style="font-size:0.88rem;line-height:1.5;"> EVM-12Lドライバーの音響物理、サンプル精度（$t=0$）のアライメント、左右テイクの微細な差異、そして<strong>1本のDAWトラックだけで広大なステレオ空間</strong>を生み出すテクニックを解説。 </p><div class="rock-card-footer" style="margin-top:1rem;"><a href="/ja/audio-mics-guide" class="rock-btn rock-btn-primary" style="padding:0.4rem 0.9rem;font-size:0.82rem;">完全ガイドを読む ➔</a></div></div></div></div><hr><h2 id="📖-トーン・ヒストリー-スタジオ年代記" tabindex="-1">📖 トーン・ヒストリー＆スタジオ年代記 <a class="header-anchor" href="#📖-トーン・ヒストリー-スタジオ年代記" aria-label="Permalink to &quot;📖 トーン・ヒストリー＆スタジオ年代記&quot;">​</a></h2><div class="rock-grid" style="margin-top:1.5rem;margin-bottom:2rem;"><div class="rock-card"><div class="rock-card-content"><div style="font-size:0.75rem;text-transform:uppercase;color:var(--vp-c-brand-1);font-weight:bold;margin-bottom:0.35rem;">機材ヒストリー</div><h3 class="rock-card-title" style="font-size:1.15rem;margin-bottom:0.5rem;">不滅のトーン・キング：Electro-Voice EVM-12L</h3><p class="rock-card-desc" style="font-size:0.88rem;line-height:1.5;"> ギタートーンの常識を覆した300Wスピーカーの歴史。なぜキース・リチャーズ、SRV、ザック・ワイルド、ボナマッサがこのスピーカーを唯一無二の武器としたのか。 </p><div class="rock-card-footer" style="margin-top:1rem;"><a href="/ja/electro-voice-evm12l" class="rock-btn rock-btn-primary" style="padding:0.4rem 0.9rem;font-size:0.82rem;">ストーリーを読む ➔</a></div></div></div><div class="rock-card"><div class="rock-card-content"><div style="font-size:0.75rem;text-transform:uppercase;color:var(--vp-c-brand-1);font-weight:bold;margin-bottom:0.35rem;">スタジオ年代記</div><h3 class="rock-card-title" style="font-size:1.15rem;margin-bottom:0.5rem;">「ストーンズはアンプに金を払わない」：Mesa/Boogie 1978–1981</h3><p class="rock-card-desc" style="font-size:0.88rem;line-height:1.5;"> パリセッションとUSツアー期において、キース・リチャーズとローリング・ストーンズがいかにしてMesa Mark I / II を導入し、黄金期のトーンを築き上げたのか。 </p><div class="rock-card-footer" style="margin-top:1rem;"><a href="/ja/history-mesa-stones" class="rock-btn rock-btn-primary" style="padding:0.4rem 0.9rem;font-size:0.82rem;">年代記を読む ➔</a></div></div></div></div>',11)])])}const v=a(s,[["render",i]]);export{p as __pageData,v as default};
